create or replace function public.public_product_discovery(p_tenant uuid,p_query text default null,p_category text default null,p_min_price numeric default null,p_max_price numeric default null,p_in_stock boolean default null,p_sort text default 'relevance',p_limit integer default 48,p_offset integer default 0) returns table(product_id uuid,slug text,name text,summary text,category_name text,category_slug text,cover_url text,price numeric,currency text,stock bigint,avg_rating numeric,review_count bigint,total_count bigint) language plpgsql stable security definer set search_path=public as $$declare q text:=trim(coalesce(p_query,''));pro boolean:=public.has_entitlement(p_tenant,'search.pro');expanded text[]:=array[]::text[];begin if pro and length(q)>=2 then select coalesce(array_agg(distinct x),'{}') into expanded from(select q x union all select unnest(s.synonyms) from public.product_search_synonyms s where s.tenant_id=p_tenant and s.active and (lower(s.term)=lower(q) or lower(q)=any(select lower(z) from unnest(s.synonyms) z)))e;end if;return query with base as(select p.id product_id,p.slug,p.name,p.summary,c.name category_name,c.slug category_slug,(select ma.public_url from public.product_media pm join public.media_assets ma on ma.id=pm.media_id where pm.product_id=p.id order by pm.sort_order,pm.created_at limit 1)cover_url,coalesce((select min(v.price) from public.product_variants v where v.product_id=p.id and v.status='active'),0)price,coalesce((select min(v.currency) from public.product_variants v where v.product_id=p.id and v.status='active'),'IRR')currency,coalesce((select sum(v.inventory_quantity)::bigint from public.product_variants v where v.product_id=p.id and v.status='active'),0)stock,coalesce((select avg(r.rating)::numeric from public.product_reviews r where r.product_id=p.id and r.status='approved'),0)avg_rating,coalesce((select count(*)::bigint from public.product_reviews r where r.product_id=p.id and r.status='approved'),0)review_count,case when q='' then 0 else greatest(similarity(p.name,q),similarity(coalesce(p.summary,''),q),coalesce((select max(similarity(p.name,x)) from unnest(expanded)x),0)) end relevance,case when pro then coalesce((select (case when rr.pinned then 1000 else 0 end)+rr.boost from public.product_search_ranking_rules rr where rr.tenant_id=p_tenant and rr.product_id=p.id and rr.active and(rr.starts_at is null or rr.starts_at<=now())and(rr.ends_at is null or rr.ends_at>=now())),0) else 0 end merch from public.products p left join public.product_categories c on c.id=p.category_id and c.tenant_id=p.tenant_id where p.tenant_id=p_tenant and p.status='active'),filtered as(select * from base where(q='' or name ilike '%'||q||'%' or coalesce(summary,'') ilike '%'||q||'%' or relevance>.12 or(pro and exists(select 1 from unnest(expanded)x where name ilike '%'||x||'%' or coalesce(summary,'') ilike '%'||x||'%')))and(p_category is null or category_slug=p_category)and(p_min_price is null or price>=p_min_price)and(p_max_price is null or price<=p_max_price)and(p_in_stock is null or(p_in_stock and stock>0)or(not p_in_stock and stock<=0)))select f.product_id,f.slug,f.name,f.summary,f.category_name,f.category_slug,f.cover_url,f.price,f.currency,f.stock,f.avg_rating,f.review_count,count(*)over() from filtered f order by case when p_sort='price_asc' then f.price end asc,case when p_sort='price_desc' then f.price end desc,case when p_sort='rating' then f.avg_rating end desc,case when p_sort='newest' then f.product_id end desc,f.merch desc,f.relevance desc,f.name asc limit greatest(1,least(p_limit,100)) offset greatest(0,p_offset);end$$;
create or replace function public.public_zero_result_recovery(p_tenant uuid,p_query text,p_limit integer default 6) returns table(slug text,name text,cover_url text,price numeric,currency text,reason text) language plpgsql stable security definer set search_path=public as $$declare q text:=trim(coalesce(p_query,''));begin if not public.has_entitlement(p_tenant,'search.pro') or length(q)<2 then return;end if;return query select p.slug,p.name,(select ma.public_url from public.product_media pm join public.media_assets ma on ma.id=pm.media_id where pm.product_id=p.id order by pm.sort_order,pm.created_at limit 1),coalesce((select min(v.price) from public.product_variants v where v.product_id=p.id and v.status='active'),0),coalesce((select min(v.currency) from public.product_variants v where v.product_id=p.id and v.status='active'),'IRR'),'پیشنهاد نزدیک'::text from public.products p where p.tenant_id=p_tenant and p.status='active' order by greatest(similarity(p.name,q),similarity(coalesce(p.summary,''),q)),coalesce((select rr.boost+(case when rr.pinned then 1000 else 0 end) from public.product_search_ranking_rules rr where rr.tenant_id=p_tenant and rr.product_id=p.id and rr.active),0) desc,p.created_at desc limit greatest(1,least(p_limit,12));end$$;grant execute on function public.public_zero_result_recovery(uuid,text,integer) to anon,authenticated;